/* IDO 7.1 NCC (C++) EXACT donor for gui_func_00000F04 (313 words, 1252 bytes): spliced over the empty
 * placeholder in gui_uso.c on both build trees (REPLACE_FUNC_BODY). agent-g run 294: EXACT (kit CCCLXVI).
 * History (was the NON_MATCHING comparison donor gui_uso_ncc_0F04_nm.cpp):
 * agent-g run 165 (docs/IDO_CODEGEN.md kit CV): the string blitter rewritten as C++ in the 329C / 2DE0
 * style -- each append is the font context's inline Ctx::next() (n read, n + 1 stored, &buf[n]) passed as
 * the pkt of the stock 2.0I gbi.h gSPTexture / gSPScisTextureRectangle macros. Two source-order facts from
 * the target: x = x0 + cx * sx is computed BEFORE the glyph-index call (the target converts x0 into a
 * callee-saved FP register there), and the glyph's u / v / w are read into named locals before the load
 * call (u, v, w loaded first, then the call's other arguments). cy / c declared last puts their homes at
 * the target's 212 / 211; per glyph fh, then x, then y (best of the 6 orders). No empty tests, no pads.
 * 97.25 standalone (cfe NM 91.58).
 * LEFT: first-append dl / n colours swapped (target dl v0, n v1), second MAX temp v0 (target a0), frame
 * 272 vs 264.
 * run 172 (kit CXVII): the texture rectangle's slot through a post-increment-in-index next
 * (`&dl->buf[dl->n++]`): 97.25 -> 97.35 (the 1A44 increment-spelling lever).
 * run 173 (kit CXIX): the texture append's next() as `int n; n = dl->n; dl->n++;` (read into n, then a
 * separate post-increment of the field; a 6 x 6 spelling grid over the two sites): 97.35 -> 97.44.
 * agent-c run 190 (kit CLVIII): the rectangle's three appends as separate macro packets (pkt / pkt2 / pkt3,
 * the 329C / 3714 kit CLVII recipe), gridded with the texture append (4^4 spellings): texture
 * `&dl->buf[dl->n++]`, rect `n = dl->n; dl->n++`, RDPHALF_1 `n = dl->n; dl->n = n + 1`, RDPHALF_2
 * `&dl->buf[dl->n++]`: 97.44 -> 98.51 standalone, length 1252 = target. */
typedef float f32; typedef int s32; typedef unsigned int u32; typedef short s16;
extern "C" { extern char D_00000000; extern int gui_func_00000000(...); }
#define _SHIFTL(v, s, w) ((unsigned int) (((unsigned int)(v) & ((0x01 << (w)) - 1)) << (s)))
#define MAX(a, b) ((a) > (b) ? (a) : (b))
#define MIN(a, b) ((a) < (b) ? (a) : (b))
struct Gwords { unsigned int w0, w1; };
union Gfx { Gwords words; long long force_structure_alignment; };
#define G_TEXTURE 0xbb
#define G_TEXRECT 0xe4
#define G_RDPHALF_1 0xb4
#define G_RDPHALF_2 0xb3
#define gImmp1(pkt, c, p0) { Gfx *_g = (Gfx *)(pkt); _g->words.w0 = _SHIFTL((c), 24, 8); _g->words.w1 = (unsigned int)(p0); }
#define gSPTexture(pkt, s, t, level, tile, on) \
{ Gfx *_g = (Gfx *)(pkt); \
	_g->words.w0 = (_SHIFTL(G_TEXTURE, 24, 8) | _SHIFTL(0, 16, 8) | _SHIFTL(level, 11, 3) | _SHIFTL(tile, 8, 3) | _SHIFTL(on, 0, 8)); \
	_g->words.w1 = (_SHIFTL(s, 16, 16) | _SHIFTL(t, 0, 16)); }
#define gSPScisTextureRectangle(pkt, pkt2, pkt3, xl, yl, xh, yh, tile, s, t, dsdx, dtdy) \
{ Gfx *_g = (Gfx *)(pkt); \
    _g->words.w0 = (_SHIFTL(G_TEXRECT, 24, 8) | _SHIFTL(MAX((s16)(xh),0), 12, 12) | _SHIFTL(MAX((s16)(yh),0), 0, 12)); \
    _g->words.w1 = (_SHIFTL((tile), 24, 3) | _SHIFTL(MAX((s16)(xl),0), 12, 12) | _SHIFTL(MAX((s16)(yl),0), 0, 12)); \
    gImmp1(pkt2, G_RDPHALF_1, (_SHIFTL(((s) - (((s16)(xl) < 0) ? (((s16)(dsdx) < 0) ? (MAX((((s16)(xl)*(s16)(dsdx))>>7),0)) : (MIN((((s16)(xl)*(s16)(dsdx))>>7),0))) : 0)), 16, 16) | \
                 _SHIFTL(((t) - (((yl) < 0) ? (((s16)(dtdy) < 0) ? (MAX((((s16)(yl)*(s16)(dtdy))>>7),0)) : (MIN((((s16)(yl)*(s16)(dtdy))>>7),0))) : 0)), 0, 16))); \
    gImmp1(pkt3, G_RDPHALF_2, (_SHIFTL((dsdx), 16, 16) | _SHIFTL((dtdy), 0, 16))); }
/* agent-g run 293 (kit CCCLXV shared packet pointers): the same macros writing through a caller-named Gfx pointer, so
 * packets the target keeps in one register share one variable (texture / TEXRECT / RDPHALF_2 = gpa, RDPHALF_1 = gpb;
 * all 15 partitions of the four packets tried): 99.744 -> 99.764 */
#define gImmp1S(VV, pkt, c, p0) { VV = (Gfx *)(pkt); VV->words.w0 = _SHIFTL((c), 24, 8); VV->words.w1 = (unsigned int)(p0); }
#define gSPTextureS(VV, pkt, s, t, level, tile, on) \
{ VV = (Gfx *)(pkt); \
	VV->words.w0 = (_SHIFTL(G_TEXTURE, 24, 8) | _SHIFTL(0, 16, 8) | _SHIFTL(level, 11, 3) | _SHIFTL(tile, 8, 3) | _SHIFTL(on, 0, 8)); \
	VV->words.w1 = (_SHIFTL(s, 16, 16) | _SHIFTL(t, 0, 16)); }
#define gSPScisTextureRectangleS(V1, V2, V3, pkt, pkt2, pkt3, xl, yl, xh, yh, tile, s, t, dsdx, dtdy) \
{ V1 = (Gfx *)(pkt); \
    V1->words.w0 = (_SHIFTL(G_TEXRECT, 24, 8) | _SHIFTL(MAX((s16)(xh),0), 12, 12) | _SHIFTL(MAX((s16)(yh),0), 0, 12)); \
    V1->words.w1 = (_SHIFTL((tile), 24, 3) | _SHIFTL(MAX((s16)(xl),0), 12, 12) | _SHIFTL(MAX((s16)(yl),0), 0, 12)); \
    gImmp1S(V2, pkt2, G_RDPHALF_1, (_SHIFTL(((s) - (((s16)(xl) < 0) ? (((s16)(dsdx) < 0) ? (MAX((((s16)(xl)*(s16)(dsdx))>>7),0)) : (MIN((((s16)(xl)*(s16)(dsdx))>>7),0))) : 0)), 16, 16) | \
                 _SHIFTL(((t) - (((yl) < 0) ? (((s16)(dtdy) < 0) ? (MAX((((s16)(yl)*(s16)(dtdy))>>7),0)) : (MIN((((s16)(yl)*(s16)(dtdy))>>7),0))) : 0)), 0, 16))); \
    gImmp1S(V3, pkt3, G_RDPHALF_2, (_SHIFTL((dsdx), 16, 16) | _SHIFTL((dtdy), 0, 16))); }
template <class T> inline T *me(T *p) { return p; } /* zero-code accessor (kit CCLXXXIV) */
struct DL { Gfx *buf; int n; };
struct Ctx { char pad[0xC]; DL *dl; Gfx *next() { int n; n = dl->n; dl->n++; return &dl->buf[n]; }
    Gfx *nextc() { return &dl->buf[dl->n++]; }
    Gfx *nR1() { Gfx *r = &dl->buf[dl->n++]; return r; } /* agent-g run 294: named result (the RDPHALF_2 append) */
    Gfx *nextp() { int n = dl->n; dl->n = n + 1; return &dl->buf[n]; } };
struct Glyph { int u; int v; int w; int adv; int pad; };
struct Font { char p0[4]; int tex; char p8[8]; int h10; int h14; int tw; int th; Glyph *glyphs; Ctx *ctx;
    Ctx *gc() { return ctx; } /* agent-g run 293: member getter (zero-code; its `this` is one more edg pool temp) */ };
extern "C" int gl_func_00000000(...);
/* agent-g run 294: the glyph texture-load call through a VOID alias (its result is never read; the target's
 * TEXRECT append right after the call takes v0 for dl, which a discarded int result keeps busy) */
extern "C" void gui_func_00000F04_load(...);
extern "C" void gui_func_00000F04(Font *f, s32 x0, s32 y0, f32 sx, f32 sy, unsigned char *str) {
    f32 cx;
    s32 h;
    unsigned char *p;
    unsigned int i;
    s32 x, y, w;
    f32 fw, fh;
    s32 idx;
    s32 u, v;
    f32 cy;
    unsigned char c;
    /* agent-g run 294: the packet pointers declared AFTER cy / c (their homes then sit below cy, which moves cy / c to the
     * target's 212 / 211) plus two dead-stored frame words (two more homes below c: frame 256 -> the target's 264):
     * 99.764 -> 99.808 (the two dead-stored words were later replaced by the named n / r homes of the TEXRECT
     * nextp() and RDPHALF_2 nR1() appends, below) */
    Gfx *gpa, *gpb;
    h = f->h14;
    /* agent-g run 292: the texture and RDPHALF_2 appends through a nested zero-code accessor me(me(f->ctx))
     * (kit CCLXXXIV per-pkt accessor grid, 81 + 241 combos): 98.588 -> 98.843 standalone */
    gSPTextureS(gpa, me(me(f->ctx))->nextc(), 0x8000, 0x8000, 0, 0, 1);
    cx = -((f32)gl_func_00000000(f, str) / 2.0f) - 2.0f;
    cy = -((f32)f->h10 / 2.0f);
    for (p = str, i = 0; i < (unsigned int)gl_func_00000000(str); p++, i++) {
        if (*p != ' ') {
            fh = h * sy;
            x = (f32)x0 + cx * sx;
            y = (f32)y0 + cy * sy;
            idx = gl_func_00000000(*p);
            c = idx;
            u = f->glyphs[idx].u;
            v = f->glyphs[idx].v;
            w = f->glyphs[idx].w;
            gui_func_00000F04_load(f->ctx, f->tex, f->tw, f->th, u, v, w, h, 0);
            fw = w * sx;
            /* agent-g run 293: joint accessor-depth x append-method grid over the three rect packets (depth 0-3,
             * next / nextp / nextc; 200 random of 1728, then a local search): the TEXRECT packet through
             * nextc() at depth 3 and the RDPHALF_2 packet back at depth 0: 98.843 -> 99.681; then the ctx read of the
             * TEXRECT / RDPHALF_2 packets through the gc() member getter (the RDPHALF_2 one via me(f)): -> 99.744 */
            /* agent-g run 294: with the void load the TEXRECT append through nextp() (joint grid): 99.808 -> 99.904;
             * the RDPHALF_2 append as me(f->gc())->nR1() (receiver grid): -> 99.994, its named r the frame's last
             * home word, so the run-294 dead-stored frame word goes: EXACT */
            gSPScisTextureRectangleS(gpa, gpb, gpa, me(me(me(f->gc())))->nextp(), f->ctx->nextp(), me(f->gc())->nR1(), x << 2, y << 2, (x + (s32)fw) << 2, (y + (s32)fh) << 2, 0, 0, 0,
                (s32)(((f32)(w - 1) * 1024.0f) / fw), (s32)(((f32)(h - 1) * 1024.0f) / fh));
            cx += (f32)f->glyphs[c].adv;
        } else {
            cx += (f32)f->glyphs[0].adv;
        }
    }
}
